const patch = "*** Begin Patch
*** Add File: recommendations.json
+{
+  "stages": {
+    "prototype": {
+      "level": 4,
+      "rationale": "For isolated, disposable exploration, speed and learning matter more than maintainability, so accepting code based on whether it works is reasonable. Keep it away from real user data, credentials, and systems where mistakes could cause harm."
+    },
+    "proof-of-concept": {
+      "level": 3,
+      "rationale": "A demo can use AI-written code with selective review and behavior checks, especially when its limits are clear. Verify the paths shown to stakeholders and avoid presenting a rough demo as production-ready."
+    },
+    "mvp": {
+      "level": 3,
+      "rationale": "Early users create real reliability, privacy, and security obligations, so every change should be exercised with tests and reviewed for meaningful risks. Selective review can preserve speed, but code affecting sensitive data, access control, or core flows deserves close scrutiny."
+    },
+    "production": {
+      "level": 2,
+      "rationale": "Paying customers and ongoing maintenance make each change part of a system the team must understand and support. Have a person review every change line by line, with automated tests and normal release safeguards alongside that review."
+    },
+    "critical": {
+      "level": 1,
+      "rationale": "For regulated or safety-critical systems, use AI for suggestions while qualified people write or rewrite every line and retain required traceability. Apply domain-specific verification, independent review, and approval controls before changes reach the system."
+    }
+  },
+  "summary": "Allow the most autonomy for disposable prototypes, then tighten human authorship and review as real users, customer commitments, maintenance, and potential harm increase. No stage should rely on 'it works' alone where real data, security, compliance, or safety is at stake."
+}
*** End Patch";
text(await tools.apply_patch(patch));

